mapper.update:
    /* Baim06Mapper.saveSiteNode */
	INSERT INTO TB_SITE_NODE (
	    CMPNY_CD
	    , SITE_CD
	    , NODE_CD
	    , NODE_NM
	    , NODE_TYPE
	    , PARENT_NODE_CD
	    , SELF_ATTD_APPRV_YN
	    , INSERT_NO
	    , INSERT_DATE
	    , UPDATE_NO
	    , UPDATE_DATE
	) VALUES (
	    #{gvCmpnyCd}
	    , #{siteCd}
	    , #{nodeCd}
	    , #{nodeNm}
	    , #{nodeType}
	    , #{parentNodeCd}
	    , #{selfAttdApprvYn}
	    , #{gvUserCd}
	    , CURRENT_TIMESTAMP
	    , #{gvUserCd}
	    , CURRENT_TIMESTAMP
	) AS NEW
	ON DUPLICATE KEY UPDATE
		NODE_NM 		   	 = NEW.NODE_NM
		, NODE_TYPE			 = NEW.NODE_TYPE
		, PARENT_NODE_CD	 = NEW.PARENT_NODE_CD
	    , SELF_ATTD_APPRV_YN = NEW.SELF_ATTD_APPRV_YN
	    , UPDATE_NO          = NEW.UPDATE_NO
	    , UPDATE_DATE        = CURRENT_TIMESTAMP

mapper.select:
/* Baim06Mapper.selectNodeCnt */ WITH RECURSIVE NODE_TREE AS ( -- 1) 시작 노드의 "직계 자식"부터 가져오기 SELECT A.* , 1 AS depth , A.NODE_CD AS path FROM TB_SITE_NODE A WHERE A.CMPNY_CD = #{gvCmpnyCd} AND A.SITE_CD = #{siteCd} AND A.NODE_CD = #{nodeCd}
UNION ALL
-- 2) 위에서 찾은 노드들의 자식을 계속 재귀적으로 확장 SELECT A.* , B.depth + 1 AS depth , CONCAT(B.path, '>', A.NODE_CD) AS path FROM TB_SITE_NODE A JOIN NODE_TREE B ON A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.PARENT_NODE_CD = B.NODE_CD ) SELECT COUNT(*) AS CNT FROM NODE_TREE ORDER BY DEPTH, NODE_CD

mapper.delete:
/* Baim06Mapper.deleteSiteNode */
DELETE FROM TB_SITE_NODE
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND NODE_CD = #{nodeCd}

    /* Baim06Mapper.deleteSiteNodeInUser */
    UPDATE TB_USER A
    SET A.NODE_CD = ''
    	, A.UPDATE_NO = #{gvUserCd}
    	, A.UPDATE_DATE = NOW()
	WHERE A.CMPNY_CD = #{gvCmpnyCd}
	  AND A.SITE_CD = #{siteCd}
	  AND NOT EXISTS (
		SELECT 1
	    FROM TB_SITE_NODE N
	    WHERE N.CMPNY_CD = A.CMPNY_CD
	      AND N.SITE_CD = A.SITE_CD
	      AND N.NODE_CD = A.NODE_CD
	      AND N.NODE_CD = 'n1'
	      AND (N.MAIN_ADMIN_CD = A.USER_ID OR N.SUB_ADMIN_CD = A.USER_CD)
	  )

/* Baim06Mapper.deleteSiteAllNode */
DELETE FROM TB_SITE_NODE
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND NODE_CD != 'n1'
  AND SITE_CD = #{siteCd}

mapper.update:
/* Baim06Mapper.deleteSiteNodeMainAdmin */
UPDATE TB_SITE_NODE
SET MAIN_ADMIN_CD = ''
    , UPDATE_NO = #{gvUserCd}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND MAIN_ADMIN_CD = #{userCd}

/* Baim06Mapper.deleteSiteNodeSubAdmin */
UPDATE TB_SITE_NODE
SET SUB_ADMIN_CD = ''
    , UPDATE_NO = #{gvUserCd}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SUB_ADMIN_CD = #{userCd}

/* Baim06Mapper.saveSiteNodeMainAdmin */
UPDATE TB_SITE_NODE
SET MAIN_ADMIN_CD = #{userCd}
    , UPDATE_NO = #{gvUserCd}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND NODE_CD = #{nodeCd}

/* Baim06Mapper.saveSiteNodeSubAdmin */
UPDATE TB_SITE_NODE
SET SUB_ADMIN_CD = #{userCd}
	, UPDATE_NO = #{gvUserCd}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND NODE_CD = #{nodeCd}

/* Baim06Mapper.updateUserNode */
UPDATE TB_USER
SET NODE_CD = #{nodeCd}
    , UPDATE_NO = #{gvUserCd}
    , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND USER_CD = #{userCd}

mapper.select:
/* Baim06Mapper.selectSiteNodeInAdmin */
SELECT COUNT(*)
FROM TB_SITE_NODE A
     INNER JOIN TB_USER B
		ON (
			A.CMPNY_CD = B.CMPNY_CD
		AND A.NODE_CD = B.NODE_CD
        AND B.USER_CD = #{userCd}
        AND B.USE_YN = 'Y'
        AND (
				(
                    NULLIF(TRIM(A.MAIN_ADMIN_CD), '') IS NOT NULL AND A.MAIN_ADMIN_CD != #{userCd}
				) 
                 OR (
 					NULLIF(TRIM(A.SUB_ADMIN_CD), '') IS NOT NULL AND A.SUB_ADMIN_CD != #{userCd}
                 )
			)
        )
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}

/* Baim06Mapper.selectSiteNodeInUser */
SELECT COUNT(*)
FROM TB_USER A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.USE_YN = 'Y'
  AND A.SITE_CD = #{siteCd}
  AND A.NODE_CD = #{nodeCd}
  AND A.USER_CD != #{userCd}

/* Baim06Mapper.selectUserNodeInfo */	
SELECT 
	A.SITE_CD		AS siteCd
	, A.NODE_CD		AS nodeCd
FROM TB_USER A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USER_CD = #{userCd}
